// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Receiver owner;

    function setUp() public {
        owner = new Receiver();
        vm.prank(address(owner));
        c = new MultiplicatorX4();
    }

    function testFuzz_property(uint256 prior, uint256 value) public {
        prior = bound(prior, 1, 1e18);
        value = bound(value, 1, 1e18);

        // fund the contract with prior funds, fund the owner so it can attach value
        vm.deal(address(c), prior);
        vm.deal(address(owner), value);

        vm.prank(address(owner));
        c.withdraw{value: value}();

        // Reference: withdraw transfers the ENTIRE balance out, contract ends at 0.
        assertTrue(address(c).balance == 0);
    }
}

contract Receiver {
    receive() external payable {}
}
